const JS="\ndocument.querySelector('.menu')?.addEventListener('click',e=>{const n=document.querySelector('.nav');const open=n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});\ndocument.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('.nav')?.classList.remove('open');document.querySelector('.menu')?.setAttribute('aria-expanded','false')}));\nconst reveal=document.querySelectorAll('.reveal');if('IntersectionObserver'in window){const io=new IntersectionObserver(es=>{for(const e of es)if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}},{threshold:.1});reveal.forEach(e=>io.observe(e))}else reveal.forEach(e=>e.classList.add('visible'));\ndocument.querySelector('#copycode')?.addEventListener('click',async e=>{try{await navigator.clipboard.writeText(document.querySelector('#codesample').textContent);e.currentTarget.textContent='COPIADO ✓';setTimeout(()=>e.currentTarget.textContent='COPIAR',1800)}catch{e.currentTarget.textContent='SELECIONE O TEXTO'}});\n";
const HTML="<!doctype html>\n<html lang=\"pt-BR\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>ARES — HTTP Server in C | The Workshop</title>\n<meta name=\"description\" content=\"ARES: um servidor HTTP/1.1 em C, construído do zero. Acompanhe a arquitetura, os experimentos e a evolução do projeto no The Workshop.\">\n<meta name=\"theme-color\" content=\"#0b0d0e\"><link rel=\"canonical\" href=\"https://workshop-labs.pages.dev/projects/ares/\">\n<meta property=\"og:type\" content=\"website\"><meta property=\"og:title\" content=\"ARES — The Workshop\"><meta property=\"og:description\" content=\"Build. Break. Understand. Rebuild. Um servidor HTTP em C, construído do zero.\">\n<link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/assets/ares.css\"><script src=\"/assets/ares.js\" defer></script></head>\n<body><div class=\"topline\"></div><div class=\"noise\" aria-hidden=\"true\"></div>\n<header class=\"header wrap\" id=\"top\"><a class=\"brand\" href=\"/\" aria-label=\"The Workshop, início\"><span class=\"mark\" aria-hidden=\"true\"><span>W</span></span><span class=\"brandcopy\"><strong>THE WORKSHOP</strong><small>BUILD / BREAK / UNDERSTAND</small></span></a><button class=\"menu\" aria-controls=\"nav\" aria-expanded=\"false\">MENU ☰</button><nav class=\"nav\" id=\"nav\" aria-label=\"Navegação principal\"><a href=\"#mission\">Missão</a><a href=\"/projects/ares/tcp-foundation/\">TCP v0.1</a><a href=\"#architecture\">Arquitetura</a><a href=\"#roadmap\">Roadmap</a><a href=\"#source\" class=\"navcta\">Ver projeto ↗</a></nav></header>\n<main>\n<section class=\"hero wrap\" aria-labelledby=\"hero-title\"><div><div class=\"micro\">// THE WORKSHOP PRESENTS — PROJECT 001</div><h1 id=\"hero-title\">AR<span class=\"outline\">E</span>S<span class=\"dot\">.</span></h1><p class=\"lead\">A máquina não é uma caixa-preta. <span style=\"color:var(--accent)\">É uma pergunta esperando resposta.</span></p><p class=\"sublead\">Um servidor HTTP/1.1 construído do zero em C. Do primeiro socket à arquitetura de produção. Uma investigação prática sobre o que acontece entre uma requisição e uma resposta.</p><div class=\"chips\"><span class=\"chip status\"><i class=\"pulse\"></i> IN DEVELOPMENT · TCP v0.1 READY</span><span class=\"chip\">C17</span><span class=\"chip\">POSIX SOCKETS</span><span class=\"chip\">HTTP/1.1</span><span class=\"chip\">LINUX</span></div><div class=\"actions\"><a class=\"btn btnprimary\" href=\"#roadmap\">EXPLORAR ROADMAP <span aria-hidden=\"true\">↗</span></a><a class=\"btn btnghost\" href=\"#architecture\">VER ARQUITETURA <span aria-hidden=\"true\">↓</span></a></div></div>\n<div class=\"term\" aria-label=\"Demonstração ilustrativa do protocolo HTTP, não é um servidor ativo\"><div class=\"termhead\"><span><span class=\"lights\" aria-hidden=\"true\"><i></i><i></i><i></i></span></span><span>ARES / PROTOCOL VIEW</span><span>SIMULATION</span></div><div class=\"termcode\"><span class=\"muted\"># ARES v0.1 · execução local ilustrativa</span>\n<span class=\"orange\">$</span> make run\n<span class=\"green\">ARES TCP v0.1 listening on 127.0.0.1:8081</span>\n\n<span class=\"muted\"># no segundo terminal</span>\n<span class=\"orange\">$</span> printf 'Hello ARES!\\n' | nc 127.0.0.1 8081\n<span class=\"green\">ARES/0.1 ECHO: Hello ARES!</span>\n\n<span class=\"muted\"># 8 integration tests passed</span>\n<span class=\"orange\">$</span> <span class=\"cursor\"></span></div><div class=\"termfoot\"><span>TRANSPORT: TCP/IP</span><span>MODE: LOCAL TCP DEMO</span></div></div></section>\n<section class=\"stripe\"><div class=\"wrap stripeinner\"><div class=\"stripeitem\"><b>01</b> NO FRAMEWORK</div><div class=\"stripeitem\"><b>02</b> FROM FIRST PRINCIPLES</div><div class=\"stripeitem\"><b>03</b> TEST EVERYTHING</div><div class=\"stripeitem\"><b>04</b> DOCUMENT THE FAILURE</div></div></section>\n<section class=\"section wrap\" id=\"mission\"><div class=\"sectionhead reveal\"><div><div class=\"micro\">// 01 — THE MISSION</div><h2>Construir para <em>entender.</em><br>Quebrar para evoluir.</h2></div><p class=\"sectionintro\">O ARES não nasce para competir com Nginx ou Caddy. Nasce para revelar cada engrenagem que normalmente fica escondida atrás de uma biblioteca.</p></div><div class=\"grid3\"><article class=\"feature reveal\"><span class=\"number\">01 / TRANSPORT</span><span class=\"icon\" aria-hidden=\"true\">⌘</span><h3>Perto do kernel.</h3><p>Sockets, descritores de arquivo, buffers, syscalls, fluxo TCP e o ciclo de vida das conexões.</p></article><article class=\"feature reveal\"><span class=\"number\">02 / PROTOCOL</span><span class=\"icon\" aria-hidden=\"true\">{ }</span><h3>Cada byte importa.</h3><p>Parsing HTTP/1.1, cabeçalhos, métodos, roteamento, respostas e limites definidos explicitamente.</p></article><article class=\"feature reveal\"><span class=\"number\">03 / ENGINEERING</span><span class=\"icon\" aria-hidden=\"true\">⟡</span><h3>Resistir ao mundo real.</h3><p>Concorrência, timeouts, logs, sanitizers, fuzzing, testes de carga e implantação com reverse proxy.</p></article></div></section>\n<section class=\"architecture\" id=\"architecture\"><div class=\"wrap\"><div class=\"sectionhead reveal\"><div><div class=\"micro\">// 02 — SYSTEM DESIGN</div><h2>Por dentro da <em>requisição.</em></h2></div><p class=\"sectionintro\">Um fluxo simples na superfície. Uma coleção de decisões difíceis por baixo. Vamos estudar uma por uma.</p></div><div class=\"pipeline reveal\"><div class=\"pipe\"><small>00 / INPUT</small><b>TCP Socket</b><span>accept() / recv()</span></div><div class=\"pipe\"><small>01 / DECODE</small><b>HTTP Parser</b><span>request line / headers</span></div><div class=\"pipe\"><small>02 / DISPATCH</small><b>Router</b><span>method + path</span></div><div class=\"pipe\"><small>03 / BUILD</small><b>Response</b><span>status / body / headers</span></div><div class=\"pipe\"><small>04 / OUTPUT</small><b>TCP Send</b><span>send() / close()</span></div></div><p class=\"note\">ESTADO ATUAL — arquitetura-alvo documentada. O pipeline não representa funcionalidades já concluídas. A implementação começa pela camada TCP na v0.1.</p></div></section>\n<section class=\"section wrap\" id=\"tcp-foundation\"><div class=\"sectionhead reveal\"><div><div class=\"micro\">// TCP FOUNDATION — EXPERIMENT 001</div><h2>O primeiro socket <em>já respondeu.</em></h2></div><p class=\"sectionintro\">Começamos pelo transporte, não pelo protocolo HTTP. A v0.1 é um servidor TCP de uma linha, isolado e testável em loopback.</p></div><div class=\"tcpshow\"><div class=\"codebox reveal\"><div class=\"codebar\"><span>ARES / TCP FOUNDATION · LOCAL DEMO</span><span class=\"tcptag\">v0.1 ✓</span></div><pre>cd ares/tcp-foundation\nmake\nmake run\n\n# em outro terminal:\nprintf 'Hello ARES!\\n' | nc 127.0.0.1 8081\n\nARES/0.1 ECHO: Hello ARES!</pre></div><div class=\"feature reveal\"><span class=\"number\">MILESTONE 001 / VALIDATED</span><span class=\"icon\">✓</span><h3>8 testes. 1 conexão por vez.</h3><p>Fragmentação TCP, limites de entrada, bytes inválidos, EOF prematuro e várias conexões sequenciais. Tudo sem expor a porta à internet.</p><div class=\"tcplinks\"><a class=\"btn btnprimary\" href=\"/projects/ares/tcp-foundation/\">ABRIR ESTUDO COMPLETO ↗</a><a class=\"btn btnghost\" href=\"https://github.com/kingmaker-lab/The-Workshop./tree/main/ares/tcp-foundation\" target=\"_blank\" rel=\"noopener noreferrer\">CÓDIGO ↗</a></div></div></div></section>\n<section class=\"section wrap\" id=\"roadmap\"><div class=\"split\"><div class=\"roadlead reveal\"><span class=\"kicker\">// 03 — DEVELOPMENT LOG</span><h2>Roadmap<br>de <span style=\"color:var(--accent)\">bancada.</span></h2><p>Sem atalhos para “production ready”. Cada etapa deverá ser implementada, testada, medida e documentada antes de avançar.</p><a class=\"btn btnghost\" href=\"#source\" style=\"margin-top:17px\">ACOMPANHAR O CÓDIGO ↗</a></div><div class=\"roadlist\"><div class=\"roadrow reveal\"><span class=\"version\">v0.1</span><div><strong><a href=\"/projects/ares/tcp-foundation/\" style=\"color:#f2ae82\">TCP Foundation ↗</a></strong><small>socket · bind · listen · accept · recv · send</small></div><a class=\"tag\" href=\"/projects/ares/tcp-foundation/\">8 TESTS ✓</a></div><div class=\"roadrow reveal\"><span class=\"version\">v0.2</span><div><strong>HTTP/1.1 Parser</strong><small>request line · headers · limits</small></div><span class=\"tag\">PLANNED</span></div><div class=\"roadrow reveal\"><span class=\"version\">v0.3</span><div><strong>Routing & Responses</strong><small>methods · status codes · handlers</small></div><span class=\"tag\">PLANNED</span></div><div class=\"roadrow reveal\"><span class=\"version\">v0.4</span><div><strong>Static Files</strong><small>file I/O · content types · path safety</small></div><span class=\"tag\">PLANNED</span></div><div class=\"roadrow reveal\"><span class=\"version\">v0.5</span><div><strong>Concurrency</strong><small>event loop · epoll · backpressure</small></div><span class=\"tag\">PLANNED</span></div><div class=\"roadrow reveal\"><span class=\"version\">v0.6–0.8</span><div><strong>Hardening & Validation</strong><small>timeouts · logs · fuzzing · benchmarks</small></div><span class=\"tag\">PLANNED</span></div><div class=\"roadrow reveal\"><span class=\"version\">v0.9</span><div><strong>Staging Deployment</strong><small>Docker · reverse proxy · observability</small></div><span class=\"tag\">PLANNED</span></div><div class=\"roadrow reveal\"><span class=\"version\">v1.0</span><div><strong>Production Candidate</strong><small>security review · release checklist</small></div><span class=\"tag\">GATED</span></div></div></div></section>\n<section class=\"codearea\" id=\"source\"><div class=\"wrap codegrid\"><div class=\"codecopy reveal\"><span class=\"micro\">// 04 — THE WORKBENCH</span><h2>Sem mágica.<br><span style=\"color:var(--accent)\">Só engenharia.</span></h2><p>O primeiro laboratório já está disponível: escutar em localhost, aceitar conexões TCP e devolver uma resposta. A implementação HTTP segue em desenvolvimento. Antes de otimizar, vamos entender.</p><p style=\"font:11px/1.9 var(--mono);color:#e0b197\">NOTA: o exemplo ao lado ilustra a sequência de chamadas. Não é um servidor completo nem código pronto para produção.</p><a class=\"btn btnprimary\" href=\"https://github.com/kingmaker-lab/The-Workshop.\" target=\"_blank\" rel=\"noopener noreferrer\">ABRIR THE WORKSHOP NO GITHUB ↗</a></div><div class=\"codebox reveal\"><div class=\"codebar\"><span>ares / tcp_lifecycle.c · CONCEPT</span><button type=\"button\" class=\"copy\" id=\"copycode\" aria-label=\"Copiar código conceitual\">COPIAR</button></div><pre id=\"codesample\">int fd = socket(AF_INET, SOCK_STREAM, 0);\n/* configurar endereço + opções */\n\nbind(fd, ...);\nlisten(fd, ...);\n\nint client = accept(fd, ...);\n/* ler, validar e responder */\n\nclose(client);\nclose(fd);</pre></div></div></section>\n</main>\n<footer class=\"footer wrap\"><div class=\"footerhero\"><div><div class=\"micro\">// THE WORKSHOP — BUILD. BREAK. UNDERSTAND. REBUILD.</div><h2>O futuro começa<br>na <span>bancada.</span></h2></div><a href=\"#top\" class=\"btn btnghost\">VOLTAR AO TOPO ↑</a></div><div class=\"footerbottom\"><span>© 2026 THE WORKSHOP · WOLFPACK / KINGMAKER<br>ARES É UM PROJETO EXPERIMENTAL. NÃO HÁ SERVIDOR C PÚBLICO ATIVO NESTA PÁGINA.</span><span>MADE FOR CURIOSITY, NOT FOR COMFORT.<br><a href=\"https://github.com/kingmaker-lab/The-Workshop.\" target=\"_blank\" rel=\"noopener noreferrer\">GITHUB ↗</a></span></div></footer>\n</body></html>";
