const security={"X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin","X-Frame-Options":"DENY","Permissions-Policy":"camera=(), microphone=(), geolocation=()","Content-Security-Policy":"default-src 'none'; base-uri 'none'; frame-ancestors 'none'; style-src 'self' 'unsafe-inline'; script-src 'self'; img-src 'self' data:; connect-src 'none'; form-action 'none'"};
export default {async fetch(request){const url=new URL(request.url);const p=url.pathname.replace(/\/+$/,'')||'/';if(p==='/assets/tcp.css')return new Response(request.method==='HEAD'?null:TCP_CSS,{headers:{'Content-Type':'text/css; charset=utf-8','Cache-Control':'public, max-age=3600','X-Content-Type-Options':'nosniff'}});if(p==='/assets/hub.css')return new Response(request.method==='HEAD'?null:HUB_CSS,{headers:{'Content-Type':'text/css; charset=utf-8','Cache-Control':'public, max-age=3600','X-Content-Type-Options':'nosniff'}});if(p==='/assets/ares.css')return new Response(CSS,{headers:{"Content-Type":"text/css; charset=utf-8","Cache-Control":"public, max-age=3600","X-Content-Type-Options":"nosniff"}});if(p==='/assets/ares.js')return new Response(JS,{headers:{"Content-Type":"application/javascript; charset=utf-8","Cache-Control":"public, max-age=3600","X-Content-Type-Options":"nosniff"}});if(p==='/favicon.svg')return new Response(ICON,{headers:{"Content-Type":"image/svg+xml; charset=utf-8","Cache-Control":"public, max-age=86400","X-Content-Type-Options":"nosniff"}});if(p==='/projects/crypto'||p==='/crypto'||p==='/crypto-labs')return Response.redirect('https://wolfpack-crypto.pages.dev/',302);if(p==='/')return new Response(request.method==='HEAD'?null:HUB_HTML,{status:200,headers:{...security,'Content-Type':'text/html; charset=utf-8','Cache-Control':'public, max-age=120'}});if(p==='/projects/ares/tcp-foundation'||p==='/ares/tcp-foundation')return new Response(request.method==='HEAD'?null:TCP_HTML,{status:200,headers:{...security,'Content-Type':'text/html; charset=utf-8','Cache-Control':'public, max-age=120'}});if(p==='/projects/ares'||p==='/ares'){return new Response(request.method==='HEAD'?null:HTML,{status:200,headers:{...security,"Content-Type":"text/html; charset=utf-8","Cache-Control":"public, max-age=120"}})}return new Response('404 — Not Found',{status:404,headers:{"Content-Type":"text/plain; charset=utf-8","X-Content-Type-Options":"nosniff"}})}};